use super::misc::laplacian_smoothing;
use super::misc::lloyd_relaxation;
use super::run::run_delaunay;
use super::tetrahedron::tetrahedron_circumcenter;
use super::tetrahedron::tetrahedron_quality;
use crate::mesh::types::{Mesh, Point};

/// Configuration for tetrahedralization
#[derive(Debug, Clone)]
pub struct TetrahedralizeConfig {
    /// Maximum circumradius to edge length ratio (quality metric)
    pub max_ratio: f64,
    /// Maximum number of smoothing iterations
    pub max_smooth_iterations: usize,
    /// Add interior points to improve quality (Lloyd's relaxation)
    pub add_interior_points: bool,
    /// Number of Lloyd relaxation iterations
    pub lloyd_iterations: usize,
    /// Preserve surface mesh exactly
    pub preserve_surface: bool,
}

impl Default for TetrahedralizeConfig {
    fn default() -> Self {
        Self {
            max_ratio: 1.5,
            max_smooth_iterations: 10,
            add_interior_points: true,
            lloyd_iterations: 5,
            preserve_surface: true,
        }
    }
}

pub(super) fn points_with_quality_steiner(
    points: &[Point],
    config: &TetrahedralizeConfig,
) -> Vec<Point> {
    let mut working_points: Vec<Point> = points.to_vec();
    if config.add_interior_points {
        // Cap the number of Steiner rounds so a pathological input cannot
        // make this function unbounded. Each round inserts a single point,
        // so the cap also bounds the final node count by `points.len() +
        // STEINER_ROUNDS`.
        const STEINER_ROUNDS: usize = 32;
        let max_ratio = config.max_ratio.max(1.0);
        let mut prev_worst: Option<f64> = None;
        for _ in 0..STEINER_ROUNDS {
            let (_nodes, tets) = run_delaunay(&working_points);
            let mut worst: Option<(f64, [usize; 4])> = None;
            for tet in &tets {
                let verts = [
                    working_points[tet[0]],
                    working_points[tet[1]],
                    working_points[tet[2]],
                    working_points[tet[3]],
                ];
                let q = tetrahedron_quality(&verts);
                if q.is_finite() && q > max_ratio {
                    match worst {
                        Some((wq, _)) if q <= wq => {}
                        _ => worst = Some((q, *tet)),
                    }
                }
            }
            let Some((q_worst, tet)) = worst else { break };
            // Early exit on diminishing returns: a full O(n^{4/3}) Delaunay
            // rebuild per inserted point dominates this pipeline, so stop when
            // the worst ratio barely moves anymore instead of burning the
            // remaining rounds for sub-percent gains.
            if let Some(prev) = prev_worst {
                let gain = prev - q_worst;
                if gain <= 1e-9 || gain / prev < 0.01 {
                    break;
                }
            }
            prev_worst = Some(q_worst);
            let verts = [
                working_points[tet[0]],
                working_points[tet[1]],
                working_points[tet[2]],
                working_points[tet[3]],
            ];
            let Some(cc) = tetrahedron_circumcenter(&verts) else {
                break;
            };
            working_points.push(cc);
        }
    }
    working_points
}

pub(super) fn postprocess_mesh(mesh: &mut Mesh, config: &TetrahedralizeConfig) {
    if config.lloyd_iterations > 0 {
        lloyd_relaxation(mesh, config.lloyd_iterations);
    }

    if config.max_smooth_iterations > 0 {
        laplacian_smoothing(mesh, config.max_smooth_iterations);
    }
}
